 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            seen.add((r, c))
            q = deque([(r, c)])
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr+1,cc),(rr-1,cc),(rr,cc+1),(rr,cc-1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            out.append((color, cells))
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    comps = _components(grid)
    markers = []
    for color, cells in comps:
        if color == bg or len(cells) < 6:
            continue
        r0 = min(r for r,c in cells); r1 = max(r for r,c in cells)
        c0 = min(c for r,c in cells); c1 = max(c for r,c in cells)
        s = set(cells)
        for ar, ac in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            hor = [(ar,c) for c in range(c0,c1+1) if (ar,c) in s]
            ver = [(r,ac) for r in range(r0,r1+1) if (r,ac) in s]
            if len(hor) >= 4 and len(ver) >= 4 and len(s) == len(hor)+len(ver)-1:
                # direction of horizontal and vertical arms from elbow
                dc = 1 if ac == c0 else -1
                dr = 1 if ar == r0 else -1
                markers.append((len(cells), color, cells, ar, ac, dr, dc))
    if not markers:
        return [row[:] for row in grid]
    _, marker_color, _, ar, ac, dr, dc = max(markers, key=lambda z:z[0])

    # The pointer selects the nearest object on the side of its horizontal
    # arm and opposite its vertical arm; equality at the corner axis is allowed.
    choices = []
    for color, cells in comps:
        if color in (bg, marker_color):
            continue
        eligible = [(r,c) for r,c in cells if (r-ar)*(-dr) > 0 and (c-ac)*dc >= 0]
        if eligible:
            dist = min(abs(r-ar)+abs(c-ac) for r,c in eligible)
            choices.append((dist, -len(cells), color, cells))
    if not choices:
        return [row[:] for row in grid]
    _, _, _, target = min(choices)
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = marker_color
    return out


